var e={"00":{title:`准备`,heading:`接上电脑，找到开发板`,goal:`让工具链和芯片“说上话”：一根数据线、正确的 USB 接口，以及你 Mac 上的串口名称。`,learn:[`USB-C 数据线与纯充电线`,`COM 口与原生 USB 口`,`串口`,`启动模式`],steps:[`把一根<b>数据</b> USB-C 线插入标有 <code>COM</code>（或 <code>UART</code>）的接口。`,`检查红色电源 LED 是否亮起。`,`运行上面的命令。应该会出现一个新的 <code>/dev/cu.usbmodem…</code> 或 <code>/dev/cu.wchusbserial…</code>。`,`告诉 Claude 串口名称，以及你的开发板有一个还是两个 USB 口。`],note:`烧录时提示 “Failed to connect”（连接失败）？按住 BOOT，点按 RST，再松开 BOOT，然后重新烧录。`},"01":{title:`你好`,heading:`认识开发板`,goal:`烧录你的第一个程序。它会打印芯片的“身份证”，并让板载 RGB LED 循环显示彩虹色。`,learn:[`setup() 和 loop()`,`串口日志`,`millis()`,`WS2812 RGB LED`],pins:{0:{role:`RGB`}},steps:[`无需接线。让线缆一直插在 <code>COM</code> 口上。`,`运行命令。等待出现 <code>Hard resetting via RTS pin…</code>。`,`读一读“身份证”：flash 应显示 <b>16 MB</b>，PSRAM 约 <b>8 MB</b>。`,`观察芯片旁边的 RGB LED 循环变色。`,`按 <code>Ctrl+C</code> 退出监视器。`],note:`LED 没有颜色？有些开发板把它接在 GPIO 38 上。修改 kit/include/pins.h 中的 PIN_RGB。`},"02":{title:`第一个电路`,heading:`面包板上的 LED`,goal:`搭建你的第一个电路，并通过输入命令来控制它。开发板在监听命令的同时，LED 会继续闪烁变化。`,learn:[`面包板的行`,`电阻`,`PWM 亮度`,`状态机`],pins:{0:{role:`LED +`},1:{role:`LED −`}},wiring:{rows:[[`GPIO 4`,`电阻 220–330 Ω`,`第一只引脚`],[`电阻`,`LED 长脚 (+)`,`另一只引脚，同一行`],[`LED 短脚 (−)`,`GND`,`蓝色电源轨或 GND 引脚`]]},steps:[`接线前先拔掉 USB。把开发板横跨在面包板的中间槽上。`,`把 GPIO 4 → 电阻 → LED 长脚连起来。LED 短脚 → GND。`,`重新插上 USB，运行命令。LED 开始“呼吸”。`,`输入 <code>blink 200</code>、<code>sos</code>、<code>level 30</code>、<code>on</code>、<code>off</code>。`],note:`还没有电阻？代码把引脚驱动电流设为最小（约 5 mA）作为安全保护。不过还是尽快加上一个。`}};export{e as default};
